#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> balloons(n);
    for (int i = 0; i < n; i++) cin >> balloons[i];

    int m = (int)n + 2;
    vector<long long> a(m, 1);
    for (int i = 0; i < n; i++) a[i + 1] = balloons[i];
    vector<vector<long long>> dp(m, vector<long long>(m, 0));
    for (int length = 2; length < m; length++) {
        for (int l = 0; l + length < m; l++) {
            int r = l + length;
            long long best = 0;
            for (int k = l + 1; k < r; k++) {
                best = max(best, dp[l][k] + dp[k][r] + a[l] * a[k] * a[r]);
            }
            dp[l][r] = best;
        }
    }
    cout << dp[0][m - 1] << "\n";

    return 0;
}

