import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] balloons = new long[(int) n];
        for (int i = 0; i < balloons.length; i++) balloons[i] = Long.parseLong(next());

        int m = (int) n + 2;
        long[] a = new long[m];
        Arrays.fill(a, 1);
        for (int i = 0; i < n; i++) a[i + 1] = balloons[i];
        long[][] dp = new long[m][m];
        for (int length = 2; length < m; length++) {
            for (int l = 0; l + length < m; l++) {
                int r = l + length;
                long best = 0;
                for (int k = l + 1; k < r; k++) {
                    best = Math.max(best, dp[l][k] + dp[k][r] + a[l] * a[k] * a[r]);
                }
                dp[l][r] = best;
            }
        }
        System.out.println(dp[0][m - 1]);
    }
}
